jsonTools.init:
function init(eli) {
  // ELI for Harvey home: greeting + stats line, OARS bar, Resume Build Draft (above the tiles);
  // Harvey tip + templates (search, recently used, other) below. Hides the sidebar. No kernel change.
  eli = eli || window.eli;
  if (!eli || !eli.dashboard || typeof eli.dashboard.registerHomeSlot !== "function") return;

  var REC_KEY = "_efh_recent_templates";
  var PIN_FLAG = "_efh_pins_v2";
  var MAIN_TILES = ["app_auto_emailer", "app_docuscrub", "app_email_formatter", "app_harvey_helper"];
  var _bdDone = null;          // last "completed" map from Build Draft's hub
  var _templates = null;       // [{ id, name, agreementType }]
  var _tplLoading = null;
  var _recent = [];            // [{ id, name, at }]
  var _topMount = null, _botMount = null;

  function esc(s) {
    return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function lsGet(k) { try { return eli.compat.lsGet(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { eli.compat.lsSet(k, v); } catch (e) { } }
  function toast(m, k) { if (typeof showToast === "function") showToast(m, k || "info"); }

  // First run only: the four main tiles. Everything else stays behind the + (users can re-pin).
  if (!lsGet(PIN_FLAG)) { lsSet("eli_dashboard_apps", JSON.stringify(MAIN_TILES)); lsSet(PIN_FLAG, "1"); }

  // ── brand: ELI with the gold boxed H (logo 4A). Re-applied if the header is redrawn. ──
  var BRAND = 'ELI<span class="_efh_h">H</span>';
  function applyBrand() {
    var els = document.querySelectorAll(".app-label");
    for (var i = 0; i < els.length; i++) if (els[i].innerHTML !== BRAND) els[i].innerHTML = BRAND;
  }
  applyBrand();
  try {
    var _brandQueued = false;
    new MutationObserver(function () {
      if (_brandQueued) return; _brandQueued = true;
      requestAnimationFrame(function () { _brandQueued = false; applyBrand(); });
    }).observe(document.body, { childList: true, subtree: true });
  } catch (e) { }

  // ── data ───────────────────────────────────────────────────────────
  function firstName() {
    try {
      var s = JSON.parse(lsGet("eli_user_settings") || "{}");
      var n = String(s.userName || lsGet("eli_user_first_name") || lsGet("userFirstName") || "").trim();
      return n ? n.split(/\s+/)[0] : "";
    } catch (e) { return ""; }
  }
  function greeting() {
    var h = new Date().getHours();
    var g = h < 12 ? "Good morning" : (h < 18 ? "Good afternoon" : "Good evening");
    var n = firstName();
    return g + (n ? ", " + n : "") + (h < 12 ? " ☕" : "");
  }
  function oarsState() {
    try { var f = eli.get && eli.get("oars", "getState"); return f ? f() : null; } catch (e) { return null; }
  }
  function oarsField(text, label) {
    var m = new RegExp(label + "[^:\\n]*:\\s*([^\\n]+)", "i").exec(text || "");
    return m ? m[1].trim().slice(0, 80) : "";
  }
  function oarsSummary(st) {
    if (!st) return null;
    var t = st.text || "";
    var type = oarsField(t, "Agreement Type") || oarsField(t, "Type of Agreement");
    var party = oarsField(t, "Third Party Name") || oarsField(t, "Counterparty");
    var ref = oarsField(t, "Agreement Request Number") || oarsField(t, "CP Ref");
    var main = [type, party].filter(Boolean).join(" · ") || st.name || "OARS data";
    return { main: main, ref: ref };
  }
  function draftInProgress() {
    var m = window._bdActiveDraftMeta;
    if (!m || !(m.templateName || m.templateId || m.auditRunId)) return null;
    if (_bdDone && _bdDone.save) return null;
    var steps = [["logic", "Customize Template"], ["templates", "Fill Fields"], ["save", "Save and/or Send"]];
    var at = null;
    if (_bdDone) for (var i = 0; i < steps.length; i++) if (!_bdDone[steps[i][0]]) { at = { n: i + 1, label: steps[i][1] }; break; }
    return { name: m.templateName || "your draft", at: at };
  }
  function loadRecent() {
    return eli.storage.get("config", REC_KEY).then(function (row) {
      _recent = (row && Array.isArray(row.value)) ? row.value : [];
    }).catch(function () { _recent = []; });
  }
  function noteRecent(id, name) {
    if (!id) return;
    _recent = [{ id: id, name: name || id, at: Date.now() }].concat(_recent.filter(function (r) { return r.id !== id; })).slice(0, 8);
    eli.storage.put("config", { key: REC_KEY, value: _recent }).catch(function () { });
  }
  function loadTemplates() {
    if (_templates) return Promise.resolve(_templates);
    if (_tplLoading) return _tplLoading;
    var d = function (k) { try { return eli.dispatch("build_draft", k); } catch (e) { return undefined; } };
    _tplLoading = Promise.resolve(d("fetchManifest")).catch(function () { }).then(function () {
      return Promise.resolve(d("listAvailableTemplates"));
    }).then(function (list) {
      _templates = (Array.isArray(list) ? list : []).filter(function (t) { return t && t.id && t.name; })
        .map(function (t) { return { id: t.id, name: String(t.name), agreementType: String(t.agreementType || ""), cached: !!t.cached }; });
      _tplLoading = null;
      return _templates;
    }).catch(function () { _tplLoading = null; _templates = []; return _templates; });
    return _tplLoading;
  }
  function shortName(n) {
    return String(n).replace(/^Grant Agreement - LETTER AGREEMENT: C\.A\.R\.E\. GRANT PROGRAM ADVISORY SERVICES$/i, "C.A.R.E. Grant Letter")
      .replace(/ Agreement$/, "");
  }
  var ICONS = [[/c\.a\.r\.e|letter agreement/i, "📨"], [/non-?disclosure|nda/i, "🔒"], [/clinical/i, "🧪"], [/consumer/i, "🧴"], [/joint development/i, "🤝"], [/material transfer/i, "🧬"],
    [/research/i, "🔬"], [/master services/i, "🏛️"], [/statement of work|sow/i, "📋"], [/consult/i, "🧭"], [/speaker/i, "🎤"], [/services/i, "🛠️"],
    [/grant/i, "🎓"], [/donation/i, "🎁"], [/amendment/i, "✏️"], [/renewal/i, "🔁"], [/termination/i, "⛔"]];
  function icon(n) { for (var i = 0; i < ICONS.length; i++) if (ICONS[i][0].test(n)) return ICONS[i][1]; return "📄"; }
  function suggested(list) {
    var st = oarsState(); if (!st || !list || !list.length) return null;
    var t = String(st.text || "").slice(0, 4000).toLowerCase(), best = null;
    list.forEach(function (x) {
      var keys = [x.name.toLowerCase(), x.agreementType.toLowerCase()].filter(function (k) { return k.length > 3; });
      keys.forEach(function (k) { if (t.indexOf(k) > -1 && (!best || k.length > best.len)) best = { tpl: x, len: k.length }; });
    });
    return best ? best.tpl : null;
  }

  // ── actions ────────────────────────────────────────────────────────
  function openTemplate(t) {
    var ask = (eli.ui && eli.ui.confirm) ? eli.ui.confirm({
      title: "Load " + t.name + "?",
      message: "Load the " + t.name + " template into this document? It replaces what's in the document now.",
      confirmText: "Load template", cancelText: "Cancel",
    }) : Promise.resolve(true);
    Promise.resolve(ask).then(function (ok) {
      if (!ok) return;
      noteRecent(t.id, t.name);
      var r;
      try { r = eli.dispatch("build_draft", "openTemplate", t.id); } catch (e) { r = undefined; }
      if (r === undefined) { toast("Build Draft isn't installed. Open Data Hub to install it.", "warn"); return; }
      Promise.resolve(r).catch(function (e) { toast("Couldn't load " + t.name + ": " + (e && e.message), "err"); });
    });
  }
  // Open the hub, then go to step i (0 Customize Template, 1 Fill Fields, 2 Save and/or Send) by pressing its row.
  function openStep(i) {
    resume();
    var t0 = Date.now();
    (function press() {
      var rows = document.querySelectorAll("button._eli3_bd_step");
      if (rows.length > i) { rows[i].click(); return; }
      if (Date.now() - t0 > 10000) return;
      setTimeout(press, 150);
    })();
  }
  function resume() { try { eli.dispatch("build_draft", "hub"); } catch (e) { } }

  // Step boxes: 1 Customize Template, 2 Fill Fields, 3 Save and/or Send. Green ✓ = done, gold = next.
  function wireHubProgress(mount) {
    var r; try { r = eli.dispatch("build_draft", "progress"); } catch (e) { r = undefined; }
    Promise.resolve(r).then(function (p) {
      if (!p) return;
      var done = p.completed || {}, keys = ["logic", "templates", "save"], labels = ["Customize Template", "Fill Fields", "Save and/or Send"];
      var next = -1; if (p.inProgress) for (var i = 0; i < 3; i++) if (!done[keys[i]]) { next = i; break; }
      var box = mount.querySelector("#_efh_steps"), hs = mount.querySelector("#_efh_hs");
      if (box) box.innerHTML = keys.map(function (k, i) {
        return '<span data-step="' + i + '" title="Go to Step ' + (i + 1) + ': ' + labels[i] + '" class="' + (done[k] ? "_efh_sd" : (i === next ? "_efh_sc" : "")) + '">' + (i + 1) + (done[k] ? " ✓" : "") + '</span>';
      }).join("");
      if (hs && p.inProgress) {
        var nm = p.templateName ? esc(shortName(p.templateName)) + " · " : "";
        hs.innerHTML = nm + (next > -1 ? "Step " + (next + 1) + " of 3 · " + labels[next] : "All steps done");
      }
      _bdDone = done;
    }).catch(function () { });
  }

  // ── painting ───────────────────────────────────────────────────────
  function paintTop(mount) {
    _topMount = mount;
    var st = oarsSummary(oarsState()), dr = draftInProgress();
    var h = '';
    h += '<div class="_efh_gbar"><div class="_efh_greet">' + esc(greeting()) + '</div>' +
      '<div class="_efh_stats" id="_efh_stats"></div></div>';
    if (st) {
      h += '<div class="_efh_oars" id="_efh_oars_btn" title="View OARS data">📂 OARS loaded: <b>' + esc(st.main) + '</b>' +
        (st.ref ? ' · ' + esc(st.ref) : '') + '</div>';
    }
    var sub = dr ? (esc(shortName(dr.name)) + " · in progress") : "Pick a template below, or open the hub";
    var boxes = '<div class="_efh_steps" id="_efh_steps"><span data-step="0">1</span><span data-step="1">2</span><span data-step="2">3</span></div>';
    h += '<div class="_efh_hub" id="_efh_hub"><div class="_efh_hl"><span class="_efh_hi">⚡</span><div>' +
      '<div class="_efh_ht">BUILD DRAFT HUB</div><div class="_efh_hs" id="_efh_hs">' + sub + '</div></div></div>' + boxes + '</div>';
    mount.innerHTML = h;
    var ob = mount.querySelector("#_efh_oars_btn");
    if (ob) ob.onclick = function () { try { eli.dispatch("oars", "showViewer"); } catch (e) { } };
    mount.querySelector("#_efh_hub").onclick = resume;
    wireHubProgress(mount);
    mount.querySelector("#_efh_steps").onclick = function (e) {
      var sp = e.target && e.target.closest ? e.target.closest("[data-step]") : null;
      if (!sp) return;
      e.stopPropagation();
      openStep(Number(sp.getAttribute("data-step")));
    };
    // Stats as ELI's sidebar reads them: the older combined record plus the live per-stat counters.
    eli.storage.get("stats", "eli_user_stats").catch(function () { return null; }).then(function (row) {
      var el = mount.querySelector("#_efh_stats"); if (!el) return;
      var live = {};
      try { if (eli.stats && typeof eli.stats.getAll === "function") live = eli.stats.getAll() || {}; } catch (e) { }
      var st = Object.assign({}, (row && typeof row === "object") ? row : {}, live);
      var tro = Array.isArray(st.unlockedTrophies) ? st.unlockedTrophies.length : (Number(st.trophiesUnlocked) || 0);
      el.innerHTML = '<span><b>' + (Number(st.totalActiveDays) || 0) + '</b> days</span>' +
        '<span><b>' + (Number(st.draftsCreated) || 0) + '</b> drafts</span>' +
        '<span class="_efh_tro">🏆 ' + tro + '</span>';
    });
  }

  function paintBottom(mount) {
    _botMount = mount;
    var dr = draftInProgress();
    var tip = dr ? "When the other side sends redlines, use EI - Review Redlines (All) in Harvey."
      : "Questions about an agreement? Ask Harvey with EI - Ask Harvey (All).";
    mount.innerHTML = '<div class="_efh_harvey">➜ ' + esc(tip) + '</div>' +
      '<div class="_efh_pill"><i></i><span>TEMPLATES</span><i></i></div>' +
      '<div id="_efh_tpl"><div class="_efh_note">Loading templates…</div></div>';
    loadTemplates().then(paintTemplates);
  }

  // Search inside the templates' text with the Template Searcher tool. Downloads any template not yet on this
  // computer first (the searcher reads the saved copies), then opens the searcher and runs the query.
  function searchInside(q) {
    q = String(q || "").trim(); if (!q) return;
    var list = _templates || [], missing = list.filter(function (t) { return !t.cached; });
    var fetchAll = missing.length ? (toast("Getting " + missing.length + " template" + (missing.length === 1 ? "" : "s") + " ready to search…", "info"),
      Promise.all(missing.map(function (t) {
        return Promise.resolve(eli.dispatch("build_draft", "fetchTemplate", t.id)).then(function () { t.cached = true; }).catch(function () { });
      }))) : Promise.resolve();
    fetchAll.then(function () {
      var ready = (eli.tools && typeof eli.tools.ensureLoaded === "function") ? eli.tools.ensureLoaded("template_searcher") : Promise.resolve();
      return Promise.resolve(ready);
    }).then(function () {
      var r; try { r = eli.dispatch("tile", "app_template_searcher"); } catch (e) { r = undefined; }
      return Promise.resolve(r);
    }).then(function () {
      var started = Date.now();
      (function waitForSearcher() {
        var inp = document.getElementById("_ts_input"), go = document.getElementById("_ts_go"), st = document.getElementById("_ts_status");
        var loading = !st || /loading/i.test(st.textContent || "");
        if (inp && go && !loading) { inp.value = q; go.click(); return; }
        if (Date.now() - started > 20000) { if (inp) inp.value = q; toast("Template Searcher is still loading. Press Search when it's ready.", "warn"); return; }
        setTimeout(waitForSearcher, 200);
      })();
    }).catch(function (e) { toast("Couldn't open Template Searcher: " + (e && e.message), "err"); });
  }

  function paintTemplates() {
    var host = _botMount && _botMount.querySelector("#_efh_tpl");
    if (!host) return;
    var list = _templates || [];
    if (!list.length) { host.innerHTML = '<div class="_efh_note">No templates yet. They appear once Build Draft is installed and online.</div>'; return; }
    var byId = {}; list.forEach(function (t) { byId[t.id] = t; });
    var q = "";
    var match = function (t) { return !q || t.name.toLowerCase().indexOf(q) > -1 || t.agreementType.toLowerCase().indexOf(q) > -1; };
    var sug = suggested(list);
    var rec = []; if (sug) rec.push(sug);
    _recent.forEach(function (r) { var t = byId[r.id]; if (t && rec.indexOf(t) === -1 && rec.length < 3) rec.push(t); });
    rec = rec.filter(match);
    var others = list.filter(function (t) { return rec.indexOf(t) === -1 && match(t); });
    var whenOf = function (id) {
      var r = _recent.filter(function (x) { return x.id === id; })[0]; if (!r) return "";
      var days = Math.floor((Date.now() - r.at) / 86400000);
      return days <= 0 ? "used today" : (days === 1 ? "used yesterday" : "used " + new Date(r.at).toLocaleDateString(undefined, { month: "short", day: "numeric" }));
    };
    var h = "";
    if (rec.length) {
      h += '<div class="_efh_sub">Recently used</div><div class="_efh_rec">' + rec.map(function (t) {
        var isSug = sug && t.id === sug.id;
        return '<div class="_efh_row' + (isSug ? ' _efh_sug' : '') + '" data-tpl="' + esc(t.id) + '" title="' + esc(t.name) + '">' +
          '<span class="_efh_ri">' + icon(t.name) + '</span><span class="_efh_rn">' + esc(shortName(t.name)) + '</span>' +
          '<span class="_efh_rm">' + esc(isSug ? "suggested from OARS" : whenOf(t.id)) + '</span></div>';
      }).join("") + '</div>';
    }
    if (others.length) {
      h += '<div class="_efh_sub">' + (rec.length ? "Other templates" : "All templates") + '</div><div class="_efh_chips">' +
        others.map(function (t) { return '<span data-tpl="' + esc(t.id) + '" title="' + esc(t.name) + '">' + icon(t.name) + ' ' + esc(shortName(t.name)) + '</span>'; }).join("") + '</div>';
    }
    h += '<div class="_efh_sbox" style="margin-top:10px"><span class="_efh_mag">🔎</span>' +
      '<input type="text" class="_efh_search" id="_efh_search" autocomplete="off" placeholder="Search inside templates, e.g. indemnity">' +
      '<span class="_efh_slab" id="_efh_go">SEARCH</span></div>';
    host.innerHTML = h;
    var sin = host.querySelector("#_efh_search");
    sin.onkeydown = function (e) { if (e.key === "Enter") searchInside(sin.value); };
    host.querySelector("#_efh_go").onclick = function () { searchInside(sin.value); };
    Array.prototype.forEach.call(host.querySelectorAll("[data-tpl]"), function (el) {
      el.onclick = function () { var t = byId[el.getAttribute("data-tpl")]; if (t) openTemplate(t); };
    });
  }

  function repaint() {
    if (_topMount && _topMount.isConnected) paintTop(_topMount);
    if (_botMount && _botMount.isConnected) paintBottom(_botMount);
  }

  eli.dashboard.registerHomeSlot("eli_harvey_home_top", function (opts) { paintTop(opts.mount); }, { order: 1, position: "above" });
  eli.dashboard.registerHomeSlot("eli_harvey_home_templates", function (opts) { paintBottom(opts.mount); }, { order: 40, position: "below" });

  loadRecent().then(repaint);
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("build_draft:hub_shown", function (p) {
      _bdDone = (p && p.completed) || null;
      var m = window._bdActiveDraftMeta;
      if (m && m.templateId && !_recent.some(function (r) { return r.id === m.templateId; })) noteRecent(m.templateId, m.templateName);
    });
    ["oars:detected", "oars:cleared", "draft:created"].forEach(function (ev) { eli.bus.on(ev, function () { setTimeout(repaint, 50); }); });
  }
  eli.register({ eli_harvey_home: { refresh: function () { _templates = null; repaint(); return true; } } });
}

jsonTools.css:
#_eli3_sidebar, ._eli3_sidebar_toggle { display: none !important; }
._efh_gbar { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 2px 2px 4px; margin-bottom: 6px; }
._efh_greet { font-family: 'Source Serif 4', Georgia, serif; font-weight: 600; color: #e5cc80; font-size: 19px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
._efh_stats { display: flex; gap: 5px; flex-wrap: wrap; justify-content: flex-end; }
._efh_stats span { border: 1px solid #2a3a6b; background: #101a36; color: #94a3b8; font: 700 9px/1.3 'Inter', sans-serif; letter-spacing: .4px; padding: 3px 6px; white-space: nowrap; }
._efh_stats b { color: #f2d866; font-size: 11px; }
._efh_stats ._efh_tro { border-color: rgba(201,162,39,0.35); color: #f2d866; }
._efh_oars { border: 1px solid rgba(201,162,39,0.35); border-left: 3px solid #c9a227; background: rgba(255,255,255,0.04); color: #f1f5f9; font: 600 11px/1.4 'Inter', sans-serif; padding: 7px 10px; cursor: pointer; margin-bottom: 8px; }
._efh_oars b { color: #f2d866; }
._efh_resume { display: flex; align-items: center; gap: 8px; border: 2px solid #c9a227; background: radial-gradient(circle at 50% 50%, rgb(201 162 39 / 0.25) 0%, #0b0f19 80%); box-shadow: inset 0 1px 0 rgba(255,255,255,0.12), 0 5px 12px rgba(0,0,0,0.7), 0 0 14px rgba(201,162,39,0.3); color: #fff; font: 800 11px/1.2 'Inter', sans-serif; letter-spacing: .6px; padding: 9px 10px; cursor: pointer; margin-bottom: 4px; }
._efh_resume small { margin-left: auto; color: #cbd5e1; font-weight: 500; letter-spacing: 0; }
._efh_harvey { border-left: 3px solid #4a9eff; background: rgba(74,158,255,0.1); color: #bcd6ff; font: 600 11px/1.4 'Inter', sans-serif; padding: 7px 10px; margin: 4px 0 2px; }
._efh_pill { display: flex; align-items: center; gap: 8px; margin: 10px 0 7px; }
._efh_pill i { flex: 1; height: 1px; background: rgba(201,162,39,0.45); }
._efh_pill span { border: 1px solid #c9a227; color: #f2d866; font: 800 9px/1 'Inter', sans-serif; letter-spacing: 1.6px; padding: 4px 9px; background: #101827; }
._efh_search_old { width: 100%; box-sizing: border-box; background: #0b1222; border: 1px solid rgba(201,162,39,0.35); color: #e2e8f0; font: 500 11.5px 'Inter', sans-serif; padding: 8px 10px; outline: none; border-radius: 0; }
._efh_search:focus { border-color: #c9a227; }
._efh_search::placeholder { color: #7d8aa5; }
._efh_rec { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
._efh_row { position: relative; display: grid; grid-template-columns: 18px minmax(0, 1fr); column-gap: 7px; align-items: center; border: 1px solid rgba(201,162,39,0.35); border-bottom-color: #000; background: radial-gradient(circle at 20% 20%, rgb(201 162 39 / 0.15) 0%, #0b0f19 70%); box-shadow: inset 0 1px 0 rgba(255,255,255,0.12), 0 5px 12px rgba(0,0,0,0.6); padding: 6px 8px; cursor: pointer; }
._efh_row:hover { border-color: #c9a227; }
._efh_ri { grid-row: 1 / 3; font-size: 14px; }
._efh_rn { color: #fff; font: 800 10.5px/1.2 'Inter', sans-serif; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
._efh_rm { grid-column: 2; color: #7d8aa5; font: 500 8.5px/1.2 'Inter', sans-serif; }
._efh_sug { border: 2px solid #c9a227; box-shadow: 0 0 12px rgba(201,162,39,0.3); }
._efh_sug ._efh_rm { color: #f2d866; }
._efh_chips { display: flex; flex-wrap: wrap; gap: 5px; }
._efh_chips span { border: 1px solid rgba(201,162,39,0.35); background: radial-gradient(circle at 20% 20%, rgb(201 162 39 / 0.15) 0%, #0b0f19 70%); box-shadow: inset 0 1px 0 rgba(255,255,255,0.12), 0 4px 8px rgba(0,0,0,0.5); color: #f1f5f9; font: 700 9.5px/1.2 'Inter', sans-serif; padding: 5px 8px; cursor: pointer; white-space: nowrap; }
._efh_chips span:hover { border-color: #c9a227; }
._efh_note { color: #94a3b8; font: 500 11px 'Inter', sans-serif; padding: 4px 2px; }
